mapper.select:
SELECT id, summary_type, period_start, period_end,
       stats_json, llm_summary, created_at
FROM ai_periodic_summary
WHERE summary_type = #{summaryType}
  AND period_start = #{periodStart}
  AND period_end = #{periodEnd}
LIMIT 1

SELECT id, summary_type, period_start, period_end,
       stats_json, llm_summary, created_at
FROM ai_periodic_summary
WHERE summary_type = #{summaryType}
ORDER BY period_end DESC, id DESC
LIMIT #{limit}
